<script setup lang="ts">const props=defineProps<{item:{id:string;state:string;risk_score:number;action:string;reason_codes:string[];signal_summary?:{code:string;score:number;explanation:string}[];trust_score:number;trust_band:string}|null}>();const emit=defineEmits<{claim:[];decide:[value:{action:'allow'|'review'|'challenge'|'block';reason:string;approverId?:string}]}>();const action=ref<'allow'|'review'|'challenge'|'block'>('challenge'),reason=ref('الگوی رفتاری غیرعادی است و باید احراز مرحله‌ای انجام شود.'),approverId=ref('22222222-2222-4222-8222-222222222222');function submit(){emit('decide',{action:action.value,reason:reason.value,...(action.value==='block'?{approverId:approverId.value}:{})})}</script>
<template><section v-if="item" class="risk-panel risk-workspace"><header><div><h2>تحلیل پرونده</h2><p>همه دلایل قابل توضیح و قابل اعتراض هستند</p></div><button v-if="item.state==='open'" class="button button-secondary" type="button" @click="emit('claim')">دریافت پرونده</button></header><div class="risk-workspace-grid"><TrustScoreCard :score="item.trust_score" :band="item.trust_band" :risk="item.risk_score"/><article class="risk-signals"><h3>سیگنال‌های مؤثر</h3><ul><li v-for="signal in item.signal_summary" :key="signal.code"><div><b>{{signal.explanation}}</b><code>{{signal.code}}</code></div><strong>{{signal.score.toLocaleString('fa-IR')}}</strong></li></ul></article></div><form class="risk-decision" @submit.prevent="submit"><label>تصمیم<select v-model="action"><option value="allow">اجازه</option><option value="review">بررسی بیشتر</option><option value="challenge">چالش احراز</option><option value="block">مسدودسازی</option></select></label><label v-if="action==='block'">تأییدکننده دوم<input v-model="approverId" required></label><label class="wide">دلیل<textarea v-model="reason" required minlength="8"></textarea></label><button class="button button-primary" type="submit">ثبت تصمیم قابل ممیزی</button></form></section><section v-else class="risk-panel"><p>پرونده‌ای برای نمایش انتخاب نشده است.</p></section></template>
